import { SortT } from "../types";
export function isDateSort(sort) {
    return sort === SortT.DateAsc || sort === SortT.DateDesc;
}
export function isPriceSort(sort) {
    return sort === SortT.PriceAsc || sort === SortT.PriceDesc;
}
export function getSortDirection(sort, ascendingSort, descendingSort) {
    if (sort === ascendingSort)
        return "ascending";
    if (sort === descendingSort)
        return "descending";
    return "none";
}
export function toggleSort(sort, ascendingSort, descendingSort) {
    return sort === descendingSort ? ascendingSort : descendingSort;
}
export function sortByDateTime(list, sortType) {
    return list.slice().sort((a, b) => {
        const dateA = new Date(a.date).getTime();
        const dateB = new Date(b.date).getTime();
        if (sortType === SortT.DateDesc) {
            return dateB - dateA;
        }
        return dateA - dateB;
    });
}
export function sortByPrice(list, sortType) {
    return list.slice().sort((a, b) => {
        const priceA = a.totalPrice;
        const priceB = b.totalPrice;
        if (sortType === SortT.PriceDesc) {
            return priceB - priceA;
        }
        return priceA - priceB;
    });
}
