    /* Typography and geometry */
    --font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    --line-width: 0.0625rem;
    --focus-ring-width: 0.25rem;
    --radius-control: 0.5rem;
    --radius-card: 0.75rem;
    --radius-modal: 0.75rem;
    --control-height: 2.75rem;
    --control-height-compact: 2.25rem;
    --sidebar-width: 14rem;
    --sidebar-collapsed-width: 4.75rem;
    --sidebar-mobile-width: 15.25rem;
    --shadow-card: 0 0.0625rem 0.1875rem var(--shadow-color-card);
    --shadow-dropdown: 0 0.5rem 1.5rem var(--shadow-color-dropdown);
    --shadow-modal: 0 1.25rem 3rem var(--shadow-color-modal);
    --shadow-zoom-hint: 0 0.1875rem 0.625rem var(--shadow-color-zoom-hint);
    --shadow-magnifier: 0 0.5rem 1.5rem var(--shadow-color-magnifier), 0 0 0 var(--line-width) var(--shadow-color-magnifier-outline);

    /* Legacy aliases retained for untouched screens. */
    --main-font-size: 1rem;
    --title-font-size-mobile: 1.25rem;
    --title-font-size-desktop: 1.5rem;
    --main-title-font-size-mobile: 1.25rem;
    --main-title-font-size-tablet: 1.875rem;
    --main-title-font-size-desktop: 2rem;
    --min-mobile-page-width: 20rem;
    --mobile-page-width: 31.25rem;
    --tablets-page-width: 43.75rem;
    --desktop-page-width: 50rem;
    --header-height: 3.75rem;
    --footer-height: 3.125rem;
    --container-padding-horizontal: 0.625rem;
    --section-margin-bottom: 1.875rem;
    --bs-body-font-family: var(--font-family);
    --bs-border-radius: var(--radius-control);
    --bs-border-radius-lg: var(--radius-card);
}
